package releaser

import (
	"fmt"
	"strconv"
	"strings"
)

const (
	hasBump = true
	hasPre  = false
	maxN    = 9999
)

var channels = []string{"nightly", "preview", "candidate"}

type ver struct {
	m, n, p int
	ch      int // -1 for none
	k       int
}

func chIndex(s string) int {
	for i, c := range channels {
		if c == s {
			return i
		}
	}
	return -1
}

func num(s string) (int, bool) {
	if len(s) < 1 || len(s) > len(strconv.Itoa(maxN)) || (len(s) > 1 && s[0] == '0') {
		return 0, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, false
		}
	}
	v, _ := strconv.Atoi(s)
	return v, v <= maxN
}

func parse(v string) (ver, bool) {
	main, pre, hasPreTxt := strings.Cut(v, "-")
	parts := strings.Split(main, ".")
	if len(parts) != 3 {
		return ver{}, false
	}
	var nums [3]int
	for i, p := range parts {
		x, ok := num(p)
		if !ok {
			return ver{}, false
		}
		nums[i] = x
	}
	t := ver{nums[0], nums[1], nums[2], -1, 0}
	if !hasPreTxt {
		return t, true
	}
	ch, n, dot := strings.Cut(pre, ".")
	ci := chIndex(ch)
	if !dot || ci < 0 {
		return ver{}, false
	}
	k, ok := num(n)
	if !ok || k < 1 {
		return ver{}, false
	}
	t.ch, t.k = ci, k
	return t, true
}

func text(t ver) string {
	s := fmt.Sprintf("%d.%d.%d", t.m, t.n, t.p)
	if t.ch >= 0 {
		s += fmt.Sprintf("-%s.%d", channels[t.ch], t.k)
	}
	return s
}

func key(t ver) [6]int {
	rel, ci, k := 0, t.ch, t.k
	if t.ch < 0 {
		rel, ci, k = 1, -1, 0
	}
	return [6]int{t.m, t.n, t.p, rel, ci, k}
}

func cmp(a, b [6]int) int {
	for i := range a {
		if a[i] != b[i] {
			if a[i] < b[i] {
				return -1
			}
			return 1
		}
	}
	return 0
}

// Release validates versions, compares and bumps them.
func Release(version, command string) string {
	cur, ok := parse(version)
	if !ok {
		return "error: version"
	}
	w := strings.Split(command, " ")
	if command == "check" {
		return "ok"
	}
	if len(w) == 2 && w[0] == "cmp" {
		other, ok := parse(w[1])
		if !ok {
			return "error: other"
		}
		switch c := cmp(key(cur), key(other)); {
		case c < 0:
			return "less"
		case c > 0:
			return "greater"
		}
		return "equal"
	}
	if hasBump && (command == "major" || command == "minor" || command == "patch") {
		m, n, p := cur.m, cur.n, cur.p
		switch {
		case command == "major":
			m, n, p = m+1, 0, 0
		case command == "minor":
			n, p = n+1, 0
		case cur.ch < 0:
			p++
		}
		if m > maxN || n > maxN || p > maxN {
			return "error: overflow"
		}
		return text(ver{m, n, p, -1, 0})
	}
	if hasPre && command == "release" {
		if cur.ch < 0 {
			return "error: not a prerelease"
		}
		cur.ch, cur.k = -1, 0
		return text(cur)
	}
	if hasPre && len(w) == 2 && w[0] == "pre" {
		ci := chIndex(w[1])
		if ci < 0 {
			return "error: channel"
		}
		switch {
		case cur.ch < 0:
			if cur.p+1 > maxN {
				return "error: overflow"
			}
			cur.p++
			cur.ch, cur.k = ci, 1
		case ci < cur.ch:
			return "error: downgrade"
		case ci == cur.ch:
			if cur.k+1 > maxN {
				return "error: overflow"
			}
			cur.k++
		default:
			cur.ch, cur.k = ci, 1
		}
		return text(cur)
	}
	return "error: command"
}

